 CREATE OR REPLACE FUNCTION public.finance_sku_order_line_details(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_marketplace_sku text DEFAULT NULL::text, p_local_sku text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_payout_filter text DEFAULT 'all'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25)+
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                     +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                  +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                  +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                       +
  SET statement_timeout TO '25s'                                                                                                                                                                                                                                                                                                                                                                                                    +
 AS $function$\r                                                                                                                                                                                                                                                                                                                                                                                                                    +
 declare\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
 v_tenant_id uuid := public.app_current_tenant_id_or_default();\r                                                                                                                                                                                                                                                                                                                                                                   +
 v_start date := coalesce(p_start, date_trunc('month', now() at time zone 'Asia/Jakarta')::date);\r                                                                                                                                                                                                                                                                                                                                 +
 v_end date := coalesce(p_end, (now() at time zone 'Asia/Jakarta')::date);\r                                                                                                                                                                                                                                                                                                                                                        +
 v_marketplace text := nullif(lower(trim(coalesce(p_marketplace,''))), '');\r                                                                                                                                                                                                                                                                                                                                                       +
 v_filter text := lower(trim(coalesce(p_payout_filter,'all')));\r                                                                                                                                                                                                                                                                                                                                                                   +
 v_local_sku text := lower(trim(coalesce(p_local_sku,'')));\r                                                                                                                                                                                                                                                                                                                                                                       +
 v_page integer := greatest(1, coalesce(p_page, 1));\r                                                                                                                                                                                                                                                                                                                                                                              +
 v_page_size integer := least(100, greatest(1, coalesce(p_page_size, 25)));\r                                                                                                                                                                                                                                                                                                                                                       +
 v_offset integer;\r                                                                                                                                                                                                                                                                                                                                                                                                                +
 v_is_unmapped boolean := false;\r                                                                                                                                                                                                                                                                                                                                                                                                  +
 v_rows jsonb;\r                                                                                                                                                                                                                                                                                                                                                                                                                    +
 v_total integer;\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 begin\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
 v_offset := (v_page - 1) * v_page_size;\r                                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 if v_marketplace in ('all','semua','_all','*','-','semua platform') then\r                                                                                                                                                                                                                                                                                                                                                         +
 v_marketplace := null;\r                                                                                                                                                                                                                                                                                                                                                                                                           +
 end if;\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 if v_filter in ('','all','semua','-') then\r                                                                                                                                                                                                                                                                                                                                                                                       +
 v_filter := 'all';\r                                                                                                                                                                                                                                                                                                                                                                                                               +
 elsif v_filter in ('settled','released','release','payout','paid','sudah payout') then\r                                                                                                                                                                                                                                                                                                                                           +
 v_filter := 'paid';\r                                                                                                                                                                                                                                                                                                                                                                                                              +
 elsif v_filter in ('pending','unpaid','belum payout','no payout','missing payout') then\r                                                                                                                                                                                                                                                                                                                                          +
 v_filter := 'unpaid';\r                                                                                                                                                                                                                                                                                                                                                                                                            +
 end if;\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 -- Detect UI "unmapped" label -> search for null local_sku in DB\r                                                                                                                                                                                                                                                                                                                                                                 +
 if v_local_sku in ('unmapped','not_mapped','tidak_dipetakan','belum dipetakan','belum_dipetakan') then\r                                                                                                                                                                                                                                                                                                                           +
 v_is_unmapped := true;\r                                                                                                                                                                                                                                                                                                                                                                                                           +
 v_local_sku := '';\r                                                                                                                                                                                                                                                                                                                                                                                                               +
 end if;\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 -- Fast path for unmapped: query marketplace_order_items directly\r                                                                                                                                                                                                                                                                                                                                                                +
 if v_is_unmapped then\r                                                                                                                                                                                                                                                                                                                                                                                                            +
 with base as (\r                                                                                                                                                                                                                                                                                                                                                                                                                   +
 select\r                                                                                                                                                                                                                                                                                                                                                                                                                           +
 o.tenant_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                     +
 o.marketplace,\r                                                                                                                                                                                                                                                                                                                                                                                                                   +
 coalesce(nullif(o.order_id::text,''), nullif(o.order_sn,''), o.marketplace_order_id::text) as order_key,\r                                                                                                                                                                                                                                                                                                                         +
 o.order_created_at,\r                                                                                                                                                                                                                                                                                                                                                                                                              +
 o.order_status,\r                                                                                                                                                                                                                                                                                                                                                                                                                  +
 o.marketplace_account_id,\r                                                                                                                                                                                                                                                                                                                                                                                                        +
 oi.marketplace_order_item_id,\r                                                                                                                                                                                                                                                                                                                                                                                                    +
 oi.marketplace_sku,\r                                                                                                                                                                                                                                                                                                                                                                                                              +
 oi.marketplace_seller_sku,\r                                                                                                                                                                                                                                                                                                                                                                                                       +
 oi.seller_sku,\r                                                                                                                                                                                                                                                                                                                                                                                                                   +
 null::text as local_sku,\r                                                                                                                                                                                                                                                                                                                                                                                                         +
 oi.marketplace_product_name,\r                                                                                                                                                                                                                                                                                                                                                                                                     +
 oi.product_name,\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 oi.marketplace_variant_name,\r                                                                                                                                                                                                                                                                                                                                                                                                     +
 oi.variant_name,\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 greatest(1, coalesce(nullif(oi.quantity,0), nullif(oi.qty,0), 1))::integer as qty,\r                                                                                                                                                                                                                                                                                                                                               +
 coalesce(oi.gross_amount, 0)::numeric as gross_amount,\r                                                                                                                                                                                                                                                                                                                                                                           +
 coalesce(oi.unit_gross_amount, 0)::numeric as unit_price,\r                                                                                                                                                                                                                                                                                                                                                                        +
 oi.marketplace_product_id,\r                                                                                                                                                                                                                                                                                                                                                                                                       +
 oi.marketplace_sku_id,\r                                                                                                                                                                                                                                                                                                                                                                                                           +
 oi.marketplace_order_id\r                                                                                                                                                                                                                                                                                                                                                                                                          +
 from public.marketplace_order_items oi\r                                                                                                                                                                                                                                                                                                                                                                                           +
 join public.marketplace_orders o\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 on o.marketplace_order_id = oi.marketplace_order_id\r                                                                                                                                                                                                                                                                                                                                                                              +
 and o.tenant_id = oi.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                   +
 where oi.tenant_id = v_tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date >= v_start\r                                                                                                                                                                                                                                                                                                         +
 and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date <= v_end\r                                                                                                                                                                                                                                                                                                           +
 and (p_account_id is null or o.marketplace_account_id = p_account_id)\r                                                                                                                                                                                                                                                                                                                                                            +
 and (\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
 v_marketplace is null\r                                                                                                                                                                                                                                                                                                                                                                                                            +
 or public._finance_marketplace_norm_20260624(o.marketplace)\r                                                                                                                                                                                                                                                                                                                                                                      +
 = public._finance_marketplace_norm_20260624(v_marketplace)\r                                                                                                                                                                                                                                                                                                                                                                       +
 )\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
 -- Exclude cancelled/unpaid/batal/failed/refunded orders\r                                                                                                                                                                                                                                                                                                                                                                         +
 and not (lower(coalesce(o.order_status, '')) ~ '(cancel|canceled|cancelled|batal|return|returned|refund|refunded|unpaid|failed|reject|in_cancel)')\r                                                                                                                                                                                                                                                                               +
 and not (lower(coalesce(o.payment_status, '')) ~ '(unpaid|failed|cancel|canceled|cancelled|refund|refunded)')\r                                                                                                                                                                                                                                                                                                                    +
 -- Exclude UUID fake orders\r                                                                                                                                                                                                                                                                                                                                                                                                      +
 and not (o.order_sn ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')\r                                                                                                                                                                                                                                                                                                                                         +
 and not (coalesce(o.order_id, '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')\r                                                                                                                                                                                                                                                                                                                           +
 -- unmapped: local_sku is null/empty on the item\r                                                                                                                                                                                                                                                                                                                                                                                 +
 and coalesce(nullif(trim(oi.local_sku),''), nullif(trim(oi.mapped_local_sku),'')) is null\r                                                                                                                                                                                                                                                                                                                                        +
 -- Filter by p_marketplace_sku and p_search in unmapped path\r                                                                                                                                                                                                                                                                                                                                                                     +
 and (\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
 p_marketplace_sku is null or p_marketplace_sku = ''\r                                                                                                                                                                                                                                                                                                                                                                              +
 or lower(p_marketplace_sku) in (\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 lower(oi.marketplace_sku::text),\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 lower(oi.marketplace_seller_sku::text),\r                                                                                                                                                                                                                                                                                                                                                                                          +
 lower(oi.seller_sku::text),\r                                                                                                                                                                                                                                                                                                                                                                                                      +
 lower(oi.marketplace_sku_id::text),\r                                                                                                                                                                                                                                                                                                                                                                                              +
 lower(oi.marketplace_product_id::text)\r                                                                                                                                                                                                                                                                                                                                                                                           +
 )\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
 )\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
 and (\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
 p_search is null or p_search = ''\r                                                                                                                                                                                                                                                                                                                                                                                                +
 or o.order_id::text ilike '%' || p_search || '%'\r                                                                                                                                                                                                                                                                                                                                                                                 +
 or coalesce(oi.marketplace_product_name, oi.product_name, '') ilike '%' || p_search || '%'\r                                                                                                                                                                                                                                                                                                                                       +
 )\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
 ),\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
 unmapped_base as (\r                                                                                                                                                                                                                                                                                                                                                                                                               +
 select b.*\r                                                                                                                                                                                                                                                                                                                                                                                                                       +
 from base b\r                                                                                                                                                                                                                                                                                                                                                                                                                      +
 left join lateral (\r                                                                                                                                                                                                                                                                                                                                                                                                              +
 select m.local_sku\r                                                                                                                                                                                                                                                                                                                                                                                                               +
 from public.marketplace_sku_maps m\r                                                                                                                                                                                                                                                                                                                                                                                               +
 where m.tenant_id = b.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                  +
 and m.marketplace_account_id = b.marketplace_account_id\r                                                                                                                                                                                                                                                                                                                                                                          +
 and m.marketplace_product_id = b.marketplace_product_id\r                                                                                                                                                                                                                                                                                                                                                                          +
 and m.marketplace_sku_id = b.marketplace_sku_id\r                                                                                                                                                                                                                                                                                                                                                                                  +
 and coalesce(m.status, 'active') = 'active'\r                                                                                                                                                                                                                                                                                                                                                                                      +
 limit 1\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
 ) m on true\r                                                                                                                                                                                                                                                                                                                                                                                                                      +
 where m.local_sku is null\r                                                                                                                                                                                                                                                                                                                                                                                                        +
 ),\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
 with_payout as (\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 select\r                                                                                                                                                                                                                                                                                                                                                                                                                           +
 u.*,\r                                                                                                                                                                                                                                                                                                                                                                                                                             +
 coalesce(fr.payout_amount, fr.received_amount, fr.net_settlement, 0)::numeric as order_payout,\r                                                                                                                                                                                                                                                                                                                                   +
 (\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
 fr.finance_report_id is not null\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 and (\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
 case\r                                                                                                                                                                                                                                                                                                                                                                                                                             +
 when lower(coalesce(u.marketplace, '')) in ('shopee', 'shopee_normal') then\r                                                                                                                                                                                                                                                                                                                                                      +
 not (upper(coalesce(fr.settlement_status, '')) ~ '(SHIPPED|DIKIRIM|RECEIVE|BELUM|PENDING|UNPAID|PERLU|READY|BATAL|CANCEL|RETURN|DITERIMA|TERIMA)')\r                                                                                                                                                                                                                                                                               +
 else\r                                                                                                                                                                                                                                                                                                                                                                                                                             +
 (coalesce(fr.payout_amount, fr.received_amount, fr.net_settlement, 0) <> 0\r                                                                                                                                                                                                                                                                                                                                                       +
 or upper(coalesce(fr.settlement_status, '')) ~ '(SETTLED|PAID|RELEASE|PAYOUT_MINUS|NEGATIVE_PAYOUT)')\r                                                                                                                                                                                                                                                                                                                            +
 end\r                                                                                                                                                                                                                                                                                                                                                                                                                              +
 )\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
 ) as has_payout,\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 (fr.finance_report_id is not null) as finance_report_exists,\r                                                                                                                                                                                                                                                                                                                                                                     +
 (coalesce(fr.payout_amount, fr.received_amount, fr.net_settlement, 0) > 0) as positive_payout_exists,\r                                                                                                                                                                                                                                                                                                                            +
 fr.settlement_status as finance_status\r                                                                                                                                                                                                                                                                                                                                                                                           +
 from unmapped_base u\r                                                                                                                                                                                                                                                                                                                                                                                                             +
 left join lateral (\r                                                                                                                                                                                                                                                                                                                                                                                                              +
 select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement, fr.settlement_status from (\r                                                                                                                                                                                                                                                                                                                +
 select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement, fr.settlement_status, 1 as priority\r                                                                                                                                                                                                                                                                                                        +
 from public.marketplace_finance_reports fr\r                                                                                                                                                                                                                                                                                                                                                                                       +
 where fr.tenant_id = u.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 and fr.marketplace_account_id = u.marketplace_account_id\r                                                                                                                                                                                                                                                                                                                                                                         +
 and fr.order_id = u.order_key\r                                                                                                                                                                                                                                                                                                                                                                                                    +
 and coalesce(fr.report_type, '') <> 'statement'\r                                                                                                                                                                                                                                                                                                                                                                                  +
 union all\r                                                                                                                                                                                                                                                                                                                                                                                                                        +
 select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement, fr.settlement_status, 2 as priority\r                                                                                                                                                                                                                                                                                                        +
 from public.marketplace_finance_reports fr\r                                                                                                                                                                                                                                                                                                                                                                                       +
 where fr.tenant_id = u.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 and fr.marketplace_account_id = u.marketplace_account_id\r                                                                                                                                                                                                                                                                                                                                                                         +
 and fr.marketplace_order_id = u.marketplace_order_id\r                                                                                                                                                                                                                                                                                                                                                                             +
 and coalesce(fr.report_type, '') <> 'statement'\r                                                                                                                                                                                                                                                                                                                                                                                  +
 union all\r                                                                                                                                                                                                                                                                                                                                                                                                                        +
 select\r                                                                                                                                                                                                                                                                                                                                                                                                                           +
 null::uuid as finance_report_id,\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 sum(coalesce(fi.received_amount, fi.net_settlement, 0)) as payout_amount,\r                                                                                                                                                                                                                                                                                                                                                        +
 sum(coalesce(fi.received_amount, fi.net_settlement, 0)) as received_amount,\r                                                                                                                                                                                                                                                                                                                                                      +
 sum(coalesce(fi.net_settlement, fi.received_amount, 0)) as net_settlement,\r                                                                                                                                                                                                                                                                                                                                                       +
 'SETTLED'::text as settlement_status,\r                                                                                                                                                                                                                                                                                                                                                                                            +
 3 as priority\r                                                                                                                                                                                                                                                                                                                                                                                                                    +
 from public.marketplace_finance_items fi\r                                                                                                                                                                                                                                                                                                                                                                                         +
 where fi.tenant_id = u.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 and fi.marketplace_account_id = u.marketplace_account_id\r                                                                                                                                                                                                                                                                                                                                                                         +
 and coalesce(nullif(fi.order_id, ''), nullif(fi.order_sn, ''), nullif(fi.external_order_id, '')) = u.order_key\r                                                                                                                                                                                                                                                                                                                   +
 and lower(u.marketplace) in ('tiktok', 'tiktok_shop')\r                                                                                                                                                                                                                                                                                                                                                                            +
 having count(*) > 0\r                                                                                                                                                                                                                                                                                                                                                                                                              +
 ) fr\r                                                                                                                                                                                                                                                                                                                                                                                                                             +
 order by priority\r                                                                                                                                                                                                                                                                                                                                                                                                                +
 limit 1\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
 ) fr on true\r                                                                                                                                                                                                                                                                                                                                                                                                                     +
 ),\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
 filtered as (\r                                                                                                                                                                                                                                                                                                                                                                                                                    +
 select *\r                                                                                                                                                                                                                                                                                                                                                                                                                         +
 from with_payout\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 where\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
 v_filter = 'all'\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 or (v_filter = 'paid' and has_payout)\r                                                                                                                                                                                                                                                                                                                                                                                            +
 or (v_filter = 'unpaid' and not has_payout)\r                                                                                                                                                                                                                                                                                                                                                                                      +
 ),\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
 counted as (\r                                                                                                                                                                                                                                                                                                                                                                                                                     +
 select count(*)::integer as total from filtered\r                                                                                                                                                                                                                                                                                                                                                                                  +
 ),\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
 paged as (\r                                                                                                                                                                                                                                                                                                                                                                                                                       +
 select * from filtered\r                                                                                                                                                                                                                                                                                                                                                                                                           +
 order by order_created_at desc, order_key, marketplace_order_item_id\r                                                                                                                                                                                                                                                                                                                                                             +
 limit v_page_size offset v_offset\r                                                                                                                                                                                                                                                                                                                                                                                                +
 )\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
 select\r                                                                                                                                                                                                                                                                                                                                                                                                                           +
 coalesce(jsonb_agg(\r                                                                                                                                                                                                                                                                                                                                                                                                              +
 jsonb_build_object(\r                                                                                                                                                                                                                                                                                                                                                                                                              +
 'id', marketplace_order_item_id,\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 'order_id', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                           +
 'order_sn', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                           +
 'marketplace', marketplace,\r                                                                                                                                                                                                                                                                                                                                                                                                      +
 'marketplace_name', marketplace,\r                                                                                                                                                                                                                                                                                                                                                                                                 +
 'created_at', order_created_at,\r                                                                                                                                                                                                                                                                                                                                                                                                  +
 'order_status', order_status,\r                                                                                                                                                                                                                                                                                                                                                                                                    +
 'status', order_status,\r                                                                                                                                                                                                                                                                                                                                                                                                          +
 'product_name', coalesce(marketplace_product_name, product_name, '-'),\r                                                                                                                                                                                                                                                                                                                                                           +
 'variant_name', coalesce(marketplace_variant_name, variant_name, '-'),\r                                                                                                                                                                                                                                                                                                                                                           +
 'marketplace_sku', coalesce(marketplace_sku, marketplace_seller_sku, seller_sku, '-'),\r                                                                                                                                                                                                                                                                                                                                           +
 'local_sku', 'Unmapped',\r                                                                                                                                                                                                                                                                                                                                                                                                         +
 'qty', qty,\r                                                                                                                                                                                                                                                                                                                                                                                                                      +
 'quantity', qty,\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 'gross_amount', gross_amount,\r                                                                                                                                                                                                                                                                                                                                                                                                    +
 'unit_price', unit_price,\r                                                                                                                                                                                                                                                                                                                                                                                                        +
 'order_payout', order_payout,\r                                                                                                                                                                                                                                                                                                                                                                                                    +
 'has_payout', has_payout,\r                                                                                                                                                                                                                                                                                                                                                                                                        +
 'finance_report_exists', finance_report_exists,\r                                                                                                                                                                                                                                                                                                                                                                                  +
 'positive_payout_exists', positive_payout_exists,\r                                                                                                                                                                                                                                                                                                                                                                                +
 'finance_status', coalesce(finance_status, ''),\r                                                                                                                                                                                                                                                                                                                                                                                  +
 'payout_status', coalesce(finance_status, '')\r                                                                                                                                                                                                                                                                                                                                                                                    +
 ) order by order_created_at desc, order_key\r                                                                                                                                                                                                                                                                                                                                                                                      +
 ), '[]'::jsonb),\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 (select coalesce(max(total),0) from counted)\r                                                                                                                                                                                                                                                                                                                                                                                     +
 into v_rows, v_total\r                                                                                                                                                                                                                                                                                                                                                                                                             +
 from paged;\r                                                                                                                                                                                                                                                                                                                                                                                                                      +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 return jsonb_build_object(\r                                                                                                                                                                                                                                                                                                                                                                                                       +
 'ok', true,\r                                                                                                                                                                                                                                                                                                                                                                                                                      +
 'source', 'unmapped_direct_join',\r                                                                                                                                                                                                                                                                                                                                                                                                +
 'rows', v_rows,\r                                                                                                                                                                                                                                                                                                                                                                                                                  +
 'total', v_total,\r                                                                                                                                                                                                                                                                                                                                                                                                                +
 'page', v_page,\r                                                                                                                                                                                                                                                                                                                                                                                                                  +
 'page_size', v_page_size,\r                                                                                                                                                                                                                                                                                                                                                                                                        +
 'total_pages', ceil(v_total::numeric / v_page_size::numeric),\r                                                                                                                                                                                                                                                                                                                                                                    +
 'total_count', v_total,\r                                                                                                                                                                                                                                                                                                                                                                                                          +
 'summary_source', 'marketplace_order_items'\r                                                                                                                                                                                                                                                                                                                                                                                      +
 );\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
 end if;\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 -- Default mapped logic\r                                                                                                                                                                                                                                                                                                                                                                                                          +
 with base_items as (\r                                                                                                                                                                                                                                                                                                                                                                                                             +
 select\r                                                                                                                                                                                                                                                                                                                                                                                                                           +
 i.marketplace_order_item_id,\r                                                                                                                                                                                                                                                                                                                                                                                                     +
 i.marketplace_order_id,\r                                                                                                                                                                                                                                                                                                                                                                                                          +
 o.marketplace,\r                                                                                                                                                                                                                                                                                                                                                                                                                   +
